/** Commands that create or convert a project, and the account commands. */
import { cmdInit } from "../../cli-ax.js";
import { formatCliVersion, PACKAGE_NAME } from "../../distribution.js";
import { cmdUpdate } from "../../update-check.js";
import { defineCommand } from "../command.js";
import { CliUsageError } from "../errors.js";
import { listValues } from "../output.js";
import { apiKeyFlag, dirFlag, dryRunFlag, fieldsFlag, jsonFlag, limitFlags, printAliasFlag, } from "../flags.js";
function parseInitSource(from, fromGrokbot) {
    if (fromGrokbot !== undefined ||
        (from !== undefined && (from === "grokbot" || from.startsWith("grokbot:")))) {
        throw new CliUsageError("Grok Bot import was removed.");
    }
    if (from === undefined) {
        return undefined;
    }
    const colon = from.indexOf(":");
    const kind = from.slice(0, colon);
    const value = from.slice(colon + 1);
    if (colon === -1 || kind !== "automation" || value === "") {
        throw new CliUsageError(`--from must be automation:<url|uuid> (got ${JSON.stringify(from)})`);
    }
    return value;
}
export const initCommand = defineCommand({
    name: "init",
    aliases: [
        {
            name: "convert-automation",
            now: "init [dir] --from automation:<url>",
            argv: (rest) => {
                const out = [];
                let url;
                let dir;
                for (let index = 0; index < rest.length; index++) {
                    const arg = rest[index] ?? "";
                    if (arg === "--dir" && index + 1 < rest.length) {
                        dir = rest[++index];
                    }
                    else if (!arg.startsWith("-") && url === undefined) {
                        url = arg;
                    }
                    else {
                        out.push(arg);
                    }
                }
                return [...(dir === undefined ? [] : [dir]), "--from", `automation:${url ?? ""}`, ...out];
            },
        },
    ],
    group: "develop",
    summary: "Scaffold an agent project, install dependencies, and print the next steps.",
    description: `
Skips files that exist, runs npm install, and runs login when unsigned.
Templates with init.json interview on a TTY. --var answers a question without
a prompt. With --json or off a TTY, each question without a default needs
--var. --json never blocks on login. With no directory, prints the setup guide.

--from automation:<url|uuid> exports a Cursor Automation (the dashboard URL
…/automations/<uuid> or …/custom-agents/<uuid>, or a bare uuid) with your
Cursor credentials. The folder defaults to ./<automation-name>. MCP servers
become Cursor-account connections. Warnings never fail the command.
--from grokbot:… and --from-grokbot fail: Grok Bot import was removed.
--dry-run prints the files it would create and writes and installs nothing.`,
    args: [{ name: "dir", description: "Folder to scaffold into." }],
    flags: {
        template: { type: "string", value: "<name>", description: "Template to scaffold." },
        var: {
            type: "string",
            multiple: true,
            value: "<id=value>",
            description: "Answer one init.json question.",
        },
        from: {
            type: "string",
            value: "<automation:url>",
            description: "Convert a Cursor Automation into a project.",
        },
        "from-grokbot": {
            type: "string",
            hidden: true,
            kind: "path",
            description: "Grok Bot import was removed.",
        },
        "dry-run": {
            type: "boolean",
            description: "Print the files it would create. Write and install nothing.",
        },
        ...jsonFlag,
        ...apiKeyFlag,
    },
    effect: "write",
    examples: [
        "agent-sdk init my-agent --template demo",
        "agent-sdk init my-agent --json --var name=triage",
        "agent-sdk init --from automation:https://cursor.com/automations/<uuid>",
    ],
    async run({ values, positionals }) {
        const automation = parseInitSource(values.from, values["from-grokbot"]);
        if (automation !== undefined) {
            const { cmdConvertAutomation } = await import("../../cli-convert-automation.js");
            return cmdConvertAutomation({
                url: automation,
                dir: positionals[0],
                json: values.json,
                apiKey: values["api-key"],
                dryRun: values["dry-run"],
            });
        }
        return cmdInit({
            dir: ".",
            initTarget: positionals[0],
            template: values.template,
            vars: values.var,
            json: values.json,
            dryRun: values["dry-run"],
        });
    },
});
export const migrateCommand = defineCommand({
    name: "migrate",
    group: "deploy",
    summary: "Start a cloud agent that moves a hosted v1 project to v2 and opens a PR.",
    description: `
Uses the bdk-migrate-v2 skill on the pushed ref. --repo, --ref, and --path are
inferred like deploy. Waits for the pull request unless --no-wait. Never
deploys. After the merge, \`agent-sdk deploy\` to the same slug replaces the v1
deployment.`,
    flags: {
        ...dirFlag,
        repo: { type: "string", value: "<url>", description: "https git repo. Defaults to origin." },
        ref: {
            type: "string",
            value: "<ref>",
            description: "Git ref. Defaults to the current branch.",
        },
        path: {
            type: "string",
            value: "<agentPath>",
            description: "Agent folder relative to the repo root. Defaults to --dir.",
        },
        "no-wait": { type: "boolean", description: "Print the cloud agent URL and exit." },
        ...jsonFlag,
        ...apiKeyFlag,
        ...dryRunFlag,
    },
    effect: "write",
    async run({ values }) {
        const { cmdMigrate } = await import("../../cli-migrate.js");
        return cmdMigrate({
            dir: values.dir,
            repo: values.repo,
            ref: values.ref,
            path: values.path,
            noWait: values["no-wait"],
            json: values.json,
            apiKey: values["api-key"],
            dryRun: values["dry-run"],
        });
    },
});
export const skillsInstallCommand = defineCommand({
    name: "skills install",
    aliases: ["install-skills"],
    group: "develop",
    parentSummary: "Manage the BDK skills for coding agents.",
    summary: "Copy the BDK skills for coding agents into ~/.cursor/skills/bdk.",
    description: "Overwrites with this package's version and sets alwaysApply so Cursor loads them. npm install already does this (postinstall).",
    flags: {
        "dry-run": {
            type: "boolean",
            description: "List the skills and the install path. Write nothing.",
        },
        ...printAliasFlag,
        ...jsonFlag,
    },
    effect: "write",
    async run({ values }) {
        const { cmdInstallSkills } = await import("../../cli-skills.js");
        return cmdInstallSkills({
            json: values.json,
            print: values["dry-run"] === true || values.print === true,
        });
    },
});
export const skillsListCommand = defineCommand({
    name: "skills list",
    group: "develop",
    summary: "List the BDK skills for coding agents and the version of each installed copy.",
    description: "--json prints { items, nextPageToken }. Each item has name, description, version (the package release), installedVersion (null when not installed, `unknown` when the installed copy has no metadata.version), and path. An installedVersion that differs from version means the copy is stale: run `agent-sdk skills install`.",
    flags: { ...limitFlags, ...fieldsFlag, ...jsonFlag },
    effect: "read",
    examples: [
        "agent-sdk skills list",
        "agent-sdk skills list --json --fields name,installedVersion",
    ],
    async run({ values }) {
        const { cmdListSkills } = await import("../../cli-skills.js");
        const list = listValues(values);
        return cmdListSkills({
            json: values.json,
            limit: list.limit,
            pageToken: list.pageToken,
            fields: list.fields,
        });
    },
});
export const loginCommand = defineCommand({
    name: "login",
    group: "account",
    summary: "Sign this host in to Cursor and store a named API key.",
    description: "Browser sign-in mints a dashboard-revocable API key. Only the key is stored. It powers inference and cursorAccount MCP connections.",
    flags: {
        ...apiKeyFlag,
        "key-name": {
            type: "string",
            value: "<name>",
            description: 'Label for the minted API key (default "bdk (<hostname>)").',
        },
        ...dryRunFlag,
    },
    effect: "write",
    async run({ values, io }) {
        if (values["dry-run"] === true) {
            await io.stdout(values["api-key"] === undefined
                ? `Dry run: would open a browser sign-in, mint an API key named ${JSON.stringify(values["key-name"] ?? "bdk (<hostname>)")}, and store it. Nothing changed.\n`
                : "Dry run: would check and store the given API key. Nothing changed.\n");
            return 0;
        }
        const { cmdLogin } = await import("../../cli-cursor.js");
        return cmdLogin({ apiKey: values["api-key"], keyName: values["key-name"] });
    },
});
export const logoutCommand = defineCommand({
    name: "logout",
    group: "account",
    summary: "Remove the stored Cursor credentials.",
    flags: { ...dryRunFlag },
    effect: "write",
    async run({ values, io }) {
        if (values["dry-run"] === true) {
            await io.stdout("Dry run: would remove the stored Cursor credentials. Nothing changed.\n");
            return 0;
        }
        const { cmdLogout } = await import("../../cli-cursor.js");
        return cmdLogout();
    },
});
export const whoamiCommand = defineCommand({
    name: "whoami",
    group: "account",
    summary: "Show which Cursor account powers this host, and why.",
    flags: { ...jsonFlag },
    effect: "read",
    async run({ values }) {
        const { cmdWhoami } = await import("../../cli-cursor.js");
        return cmdWhoami({ json: values.json });
    },
});
export const updateCommand = defineCommand({
    name: "update",
    group: "account",
    summary: "Upgrade this install to the latest published version.",
    description: "Detects global npm, pnpm, yarn, and bun installs and project dependencies.",
    flags: { ...dryRunFlag },
    effect: "write",
    async run({ values }) {
        return cmdUpdate({ dryRun: values["dry-run"] });
    },
});
export const versionCommand = defineCommand({
    name: "version",
    group: "account",
    summary: `Print the ${PACKAGE_NAME} version (also --version or -V).`,
    description: "Text output is the version number. --json prints { name, version, cli }.",
    flags: { ...jsonFlag },
    effect: "read",
    async run({ values, io }) {
        await io.stdout(formatCliVersion({ json: values.json === true }));
        return 0;
    },
});
